-- Synthetic minimal schema; not full production RLS/triggers. Runs in disposable Docker only.
BEGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$SELECT current_setting('request.jwt.claim.sub')::uuid$$;
CREATE FUNCTION can_manage_school(uuid) RETURNS boolean LANGUAGE sql AS $$SELECT auth.uid()=$1$$;
CREATE FUNCTION is_platform_admin() RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
CREATE FUNCTION teacher_belongs_to_auth(uuid) RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
CREATE FUNCTION write_school_audit(uuid,text,text,text,jsonb,jsonb,jsonb) RETURNS void LANGUAGE sql AS $$SELECT$$;
CREATE TABLE students(id uuid PRIMARY KEY,school_id uuid,class_id uuid,archived_at timestamptz,identity_status text,school_year_level text,year_level text);
CREATE TABLE schools(id uuid PRIMARY KEY,status text);
CREATE TABLE school_memberships(user_id uuid,school_id uuid,status text,role text);
CREATE TABLE academic_years(id uuid PRIMARY KEY,school_id uuid,calendar_year int);
CREATE TABLE classes(id uuid PRIMARY KEY,school_id uuid,academic_year_id uuid,status text,teacher_id uuid);
CREATE TABLE student_school_memberships(student_id uuid,school_id uuid,academic_year_id uuid,status text,ended_at timestamptz,link_method text,created_by uuid);
CREATE UNIQUE INDEX active_membership ON student_school_memberships(student_id) WHERE status='active';
CREATE TABLE class_enrollments(id uuid DEFAULT gen_random_uuid(),student_id uuid,class_id uuid,school_id uuid,academic_year_id uuid,status text,ended_at timestamptz,is_primary boolean,created_by uuid,updated_at timestamptz,UNIQUE(student_id,class_id));
CREATE TABLE student_access_entitlements(student_id uuid,access_source text,school_id uuid,academic_year_id uuid,status text,ends_at timestamptz,updated_by uuid,updated_at timestamptz,billing_status text,starts_at timestamptz,source_enrolment_id uuid,notes text,created_by uuid);
CREATE UNIQUE INDEX school_entitlement ON student_access_entitlements(student_id,school_id,academic_year_id) WHERE access_source='school';
CREATE TABLE student_school_transfer_events(student_id uuid,from_school_id uuid,to_school_id uuid,requested_by uuid,reason text);
CREATE TABLE student_identity_link_requests(id uuid,request_type text,student_id uuid,school_id uuid,requested_by uuid,status text,reviewed_by uuid,reviewed_at timestamptz,updated_at timestamptz,created_at timestamptz);
CREATE TABLE student_identity_audit_events(actor_user_id uuid,action text,student_id uuid,school_id uuid,before_state jsonb,after_state jsonb,reason text);
CREATE TABLE student_explorer_codes(student_id uuid,code text,status text);
CREATE TABLE fixture_progress(student_id uuid PRIMARY KEY,level text,week int,score int);
CREATE TABLE fixture_rewards(student_id uuid PRIMARY KEY,gems int,cards text[]);
-- TRANSFER_FUNCTION
-- ACCESS_FUNCTION
GRANT USAGE ON SCHEMA public,auth TO authenticated;
INSERT INTO schools VALUES ('00000000-0000-0000-0000-000000000001','active'),('00000000-0000-0000-0000-000000000002','active');
INSERT INTO school_memberships SELECT id,id,'active','school_admin' FROM schools;
INSERT INTO academic_years SELECT id,id,extract(year from current_date)::int FROM schools;
INSERT INTO classes SELECT id,id,id,'active',null FROM schools;
INSERT INTO students VALUES ('00000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001',null,'active','Year 5','Year 5');
INSERT INTO student_school_memberships SELECT id,school_id,school_id,'active',null,'fixture',null FROM students;
INSERT INTO class_enrollments(student_id,class_id,school_id,academic_year_id,status,is_primary) SELECT id,class_id,school_id,school_id,'active',true FROM students;
INSERT INTO student_access_entitlements(student_id,school_id,academic_year_id,access_source,status) SELECT id,school_id,school_id,'school','active' FROM students;
INSERT INTO student_explorer_codes SELECT id,'FICTIONAL-CODE','active' FROM students;
INSERT INTO fixture_progress SELECT id,'Year 4',7,90 FROM students;
INSERT INTO fixture_rewards SELECT id,25,ARRAY['fictional-card'] FROM students;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
SELECT link_existing_student_to_school('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000003','Year 5','00000000-0000-0000-0000-000000000002','Fictional transfer');
DO $$BEGIN IF NOT can_manage_school_student_learning('00000000-0000-0000-0000-000000000003') THEN RAISE EXCEPTION 'New school lacks access'; END IF; END$$;
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
DO $$BEGIN IF can_manage_school_student_learning('00000000-0000-0000-0000-000000000003') THEN RAISE EXCEPTION 'Old school retains learning access'; END IF; END$$;
RESET ROLE;
DO $$BEGIN
IF (SELECT count(*) FROM students)<>1 THEN RAISE EXCEPTION 'Duplicate student'; END IF;
IF NOT EXISTS(SELECT 1 FROM students WHERE id='00000000-0000-0000-0000-000000000003' AND school_id='00000000-0000-0000-0000-000000000002' AND class_id=school_id) THEN RAISE EXCEPTION 'Wrong school/class'; END IF;
IF EXISTS(SELECT 1 FROM class_enrollments WHERE school_id='00000000-0000-0000-0000-000000000001' AND (status='active' OR ended_at IS NULL OR is_primary)) THEN RAISE EXCEPTION 'Old enrollment active'; END IF;
IF NOT EXISTS(SELECT 1 FROM class_enrollments WHERE school_id='00000000-0000-0000-0000-000000000002' AND status='active' AND ended_at IS NULL AND is_primary) THEN RAISE EXCEPTION 'New enrollment missing'; END IF;
IF (SELECT count(*) FROM student_school_memberships WHERE status='active')<>1 THEN RAISE EXCEPTION 'Wrong active school count'; END IF;
IF NOT EXISTS(SELECT 1 FROM fixture_progress WHERE level='Year 4' AND week=7 AND score=90) OR NOT EXISTS(SELECT 1 FROM fixture_rewards WHERE gems=25 AND cards=ARRAY['fictional-card']) THEN RAISE EXCEPTION 'History altered'; END IF;
IF (SELECT count(*) FROM student_school_transfer_events)<>1 THEN RAISE EXCEPTION 'Transfer audit missing'; END IF;
IF NOT EXISTS(SELECT 1 FROM student_access_entitlements WHERE school_id='00000000-0000-0000-0000-000000000001' AND status='expired') THEN RAISE EXCEPTION 'Old entitlement active'; END IF;
IF (SELECT code FROM student_explorer_codes)<>'FICTIONAL-CODE' THEN RAISE EXCEPTION 'Code changed'; END IF;
RAISE NOTICE 'PASS transfer identity, class, enrollment, entitlements, access, audit and fixture history';
END$$;
ROLLBACK;
